content.text:
{
  "name": "实验室磁体",
  "name_en": "Laboratory Magnet",
  "manufacturer": "",
  "description": "由电流源驱动、可通过测量仪器读取磁场的实验室磁体系统，用于为样品或器件施加、测量和扫描可控磁场。",
  "description_en": "A laboratory magnet system driven by a current source and read out via a measurement instrument, used to apply, measure, and sweep a controllable magnetic field for samples or devices.",
  "tag_hints": [
    "magnetic field control",
    "field-current conversion",
    "magnet ramping",
    "laboratory magnet",
    "current-driven magnet"
  ],
  "actions": [
    {
      "action_name": "auto-BtoI",
      "description": "将目标磁场换算为所需电流。",
      "description_en": "Convert a target magnetic field to the required current."
    },
    {
      "action_name": "auto-ItoB",
      "description": "将电流换算为对应磁场。",
      "description_en": "Convert a current value to the corresponding magnetic field."
    },
    {
      "action_name": "auto-measure_field",
      "description": "测量当前磁场。",
      "description_en": "Measure the current magnetic field."
    },
    {
      "action_name": "auto-step_magfield_to_value",
      "description": "以分步方式将磁场渐变到目标值。",
      "description_en": "Ramp the magnetic field to a target value in steps."
    }
  ]
}

